{
  "name": "ingest",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "vitest run --coverage --allowOnly=false",
    "lint": "eslint . --max-warnings 0 --report-unused-disable-directives",
    "typecheck": "tsc --noEmit",
    "clean": "rm -rf dist coverage",
    "verify": "npm run lint && npm run typecheck && npm test"
  },
  "devDependencies": {
    "vitest": "^3.2.4"
  }
}
